**normalize.go**

```go
package lesson

import "strings"

func Normalize(value string) string {
	return strings.ToLower(strings.TrimSpace(value))
}
```

**normalize_test.go**

```go
package lesson

import "testing"

func wantEqual(t *testing.T, got, want string) {
	t.Helper()
	if got != want {
		t.Errorf("got %q; want %q", got, want)
	}
}

func TestNormalize(t *testing.T) {
	wantEqual(t, Normalize(" Go "), "go")
	wantEqual(t, Normalize("READY"), "ready")
}
```

**Run it**

```bash
go test ./...
go build ./...
```

`wantEqual` is compiled for the test command only. `Normalize` remains the single implementation of the production rule.

**transform.go**

```go
package lesson

import "bytes"

func Upper(input []byte) []byte {
	return bytes.ToUpper(input)
}
```

**transform_test.go**

```go
package lesson

import (
	"os"
	"path/filepath"
	"testing"
)

func TestUpperFile(t *testing.T) {
	input, err := os.ReadFile(filepath.Join("testdata", "greeting.txt"))
	if err != nil {
		t.Fatal(err)
	}
	outputPath := filepath.Join(t.TempDir(), "result.txt")
	if err := os.WriteFile(outputPath, Upper(input), 0o600); err != nil {
		t.Fatal(err)
	}
	got, err := os.ReadFile(outputPath)
	if err != nil {
		t.Fatal(err)
	}
	if string(got) != "HELLO\n" {
		t.Fatalf("got %q; want %q", got, "HELLO\n")
	}
}
```

**testdata/greeting.txt**

```text
hello
```

**Run it**

```bash
go test ./...
```

The checked-in fixture is only read. Every generated file is contained in the test's automatically managed directory.
